from collections import Counter
import re

def get_pair_counts(vocab):
    counts = Counter()
    for word_seq, freq in vocab.items():
        symbols = word_seq.split()
        for i in range(len(symbols) - 1):
            counts[(symbols[i], symbols[i+1])] += freq
    return counts

def merge_pair(pair, vocab):
    new_vocab = {}
    target = ' '.join(pair)
    merged = ''.join(pair)
    # Use regex for safe replacement (whole-token boundaries)
    pattern = re.compile(r'(?<![^ ])' + re.escape(target) + r'(?![^ ])')
    for word_seq, freq in vocab.items():
        new_seq = word_seq.replace(target, merged)
        new_vocab[new_seq] = freq
    return new_vocab

def run_bpe(vocab, num_merges):
    for step in range(num_merges):
        counts = get_pair_counts(vocab)
        if not counts:
            break
        best = max(counts, key=lambda p: (counts[p], p))
        vocab = merge_pair(best, vocab)
        print(f'Step {step+1}: merge {best[0]!r} + {best[1]!r} → {(best[0]+best[1])!r} (freq={counts[best]})')
    return vocab

vocab = {
    'l o w </w>': 5,
    'l o w e r </w>': 2,
    'n e w e s t </w>': 6,
    'w i d e s t </w>': 3,
    'n e w </w>': 8,
}

print('Running 8 steps of BPE:')
final_vocab = run_bpe(vocab, num_merges=8)
print('\nFinal vocabulary:')
for seq, freq in sorted(final_vocab.items(), key=lambda x: -x[1]):
    print(f'  {freq:3d}x {seq!r}')

